public static partial class PolishQuotes
{
    public static class AdamMickiewicz
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Czucie i wiara silniej mówi do mnie,\nNiż mędrca szkiełko i oko.\n„Martwe znasz prawdy, nieznane dla ludu,\nWidzisz świat w proszku, w każdej gwiazd iskierce;\nNie znasz prawd żywych, nie obaczysz cudu!\nMiej serce i patrzaj w serce!”", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ciemno wszędzie, głucho wszędzie,\nco to będzie, co to będzie?", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Gdy na dziewczynę zawołają: żono! Już ją żywcem pogrzebano!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kobieto! puchu marny! ty wietrzna istoto!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kto miłości nie zna, ten żyje szczęśliwy,\nI noc ma spokojną, i dzień nietęskliwy.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bo kto siedzi w Ojczyźnie i cierpi niewolę, aby zachować życie, ten straci Ojczyznę i życie; a kto opuści Ojczyznę, aby bronił Wolności narażeniem życia swego, ten obroni Ojczyznę i będzie żyć wiecznie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Litwo! Ojczyzno moja! Ty jesteś jak zdrowie;\nIle cię trzeba cenić, ten tylko się dowie,\nKto cię stracił. Dziś piękność twą w całej ozdobie\nWidzę i opisuję, bo tęsknię po tobie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Aby kraj mógł żyć, trzeba, aby żyły prawa.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bez serc, bez ducha – to szkieletów ludy.\nMłodości! podaj mi skrzydła!\nNiech nad martwym wzlecę światem\nW rajską dziedzinę ułudy…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bo dzieło zniszczenia\nW dobrej sprawie jest święte, jak dzieło tworzenia:\nBóg wyrzekł słowo ''stań się'', Bóg i ''zgiń'' wyrzecze!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Bóg sam może świat zniszczyć i drugi wystawić,\nA bez naszej pomocy nie może nas zbawić.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Gdy cię nie widzę, nie wzdycham, nie płaczę;\nNie tracę zmysłów, kiedy cię zobaczę;\nJednakże, gdy cię długo nie oglądam,\nCzegoś mi braknie, kogoś widzieć żądam,\nI tęskniąc sobie zadaję pytanie:\nCzy to jest przyjaźń, czy to jest kochanie?", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Głośniej niźli w rozmowach, Bóg przemawia w ciszy,\nI kto w sercu ucichnie, zaraz go usłyszy.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Hej, użyjmy żywota! \nWszak żyjem tylko raz; \nNiechaj ta czara złota\nRóżno wabi nas.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "I was dostrzegam, o dumni badacze!\nGdy wami burza jak śmieciem pomiata,\nZamknięci w sobie, jak w konchy ślimacze,\nChcieliście mali obejrzeć krąg świata.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Karząc plemię zwycięzców zbrodniami zatrute,\nBóg wysadzi tę ziemię, jak on swą redutę.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Kto metal kwasi, pali\nSkwasi metal i czas;\nMy ze złotych metali\nBacha ciągnijmy kwas.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Mierz siłę na zamiary,\nNie zamiar podług sił!…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Na każdem miejscu i o każdej dobie,\nGdziem z tobą płakał, gdziem się z tobą bawił,\nWszędzie i zawsze będę ja przy tobie,\nBom wszędzie cząstkę mej duszy zostawił.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Nam strzelać nie kazano. Wstąpiłem na działo\nI spojrzałem na pole — dwieście armat grzmiało.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Piękny kościół, w którym nie ma Boga.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Polały się łzy me czyste, rzęsiste\nNa me dzieciństwo sielskie, anielskie, \nNa moją młodość górną i durną, \nNa mój wiek męski, wiek klęski.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Potępi nas świętoszek, rozpustnik wyśmieje,\nŻe chociaż samotnemi otoczeni ściany,\nChociaż ona tak młoda, ja tak zakochany,\nPrzecież ja oczy spuszczam, a ona łzy leje.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Precz z moich oczu! – posłucham od razu;\nPrecz z mego serca! – i serce posłucha;\nPrecz z mej pamięci! – nie tego rozkazu,\nMoja i twoja pamięć nie posłucha.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ręce za lud walczące, sam lud poobcina,\nImion miłych ludowi – lud pozapomina…\nWszystko przejdzie. Po szumie, po huku, po trudzie,\nWezmą dziedzictwo cisi, ciemni, mali ludzie.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Rozminiem się!... I kiedyż w jedną pójdziem drogę? Ty mnie szukać nie będziesz, ja ciebie nie mogę...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Słowianie utożsamili chrześcijaństwo z niemczyzną i niewolą.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Szukam północnej gwiazdy na zamglonem niebie, \nSzukam Litwy, i domku twojego, i ciebie...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "„Świat ten jest czysta bajka!” Zgoda, przyjacielu:\nLecz każda bajka ma sens moralny na celu.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Ten może deptać węże, głaskać lwy i tury,\nKto wyrwał z siebie żądło, rogi i pazury.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "W słowach tylko chęć widzim, w działaniu potęgę;\nTrudniej dzień dobrze przeżyć, niż napisać księgę.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Wiedzcie, że dla poety jedna tylko droga:\nW sercu szukać natchnienia i dążyć do Boga!", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Witaj, jutrzenko swobody,\nZbawienia za tobą słońce!...", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Wpłynąłem na suchego przestwór oceanu\nWóz nurza się w zieloność i jak łódka brodzi,\nŚród fali łąk szumiących, śród kwiatów powodzi,\nOmijam koralowe ostrowy burzanu.", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Zwyciężonemu za pomnik grobowy\nZostaną suche drewna szubienicy,\nZa całą sławę krótki płacz kobiécy\nI długie, nocne rodaków rozmowy…", Author = "Adam Mickiewicz" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Mickiewicz", Text = "Że słyszałbym głos z Litwy... Jedźmy, nikt nie woła!", Author = "Adam Mickiewicz" },
        };
    }
}